const out=[];
for (const el of document.querySelectorAll('button, a.link-internal')) {
  const t=(el.textContent||'').trim();
  if (/character creation/i.test(t)) {
    const r=el.getBoundingClientRect();
    out.push({text:t, x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2), cls:el.className});
  }
