const want=['Both','Neither','Curvy','Pert','Chest','Red'];
const out={};
for (const el of document.querySelectorAll('button, a')) {
  const t=(el.textContent||'').trim();
  if (want.includes(t)) {
    const r=el.getBoundingClientRect();
    if (r.width>0 && r.y>0) (out[t]=out[t]||[]).push({x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height/2)});
  }
}
return JSON.stringify(out);

const out=[];
for (const el of document.querySelectorAll('*')) {
  const cs=getComputedStyle(el);
  if (cs.cursor!=='pointer'||cs.display==='none'||cs.visibility==='hidden') continue;
  if (el.children.length>0 && el.tagName!=='BUTTON' && el.tagName!=='A') continue;
  const r=el.getBoundingClientRect();
  if (r.width<8||r.height<8||r.y<360) continue;
  const txt=(el.textContent||'').trim().slice(0,22);
  if(!txt) continue;
  out.push({t:txt, tag:el.tagName, x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2)});
}
// dedup by t+y
const seen=new Set(), res=[];
for(const o of out){const k=o.t+'@'+o.y; if(seen.has(k))continue; seen.add(k); res.push(o);}
return JSON.stringify(res.slice(0,70));

const want=['Penis','Vagina','Both','Male','Female','Neither','Classic','Slender','Curvy','Soft','Flat','Budding','Tiny','Small','Pert'];
const out=[];
for (const el of document.querySelectorAll('*')) {
  if (el.children.length>0) continue;
  const t=(el.textContent||'').trim();
  if (!want.includes(t)) continue;
  const r=el.getBoundingClientRect();
  const cs=getComputedStyle(el);
  out.push({t, tag:el.tagName, cls:el.className.slice(0,30), cursor:cs.cursor, x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2)});
}
return JSON.stringify(out.slice(0,40));

const out=[];
for (const el of document.querySelectorAll('input[type=radio], .macro-cycle, .cyclingLink, a.cyclingLink')) {
  const r=el.getBoundingClientRect();
  if (r.y<600||r.y>1200) continue;
  // find nearby label text
  let lbl=''; const p=el.closest('label')||el.parentElement;
  if(p) lbl=(p.textContent||'').trim().slice(0,24);
  out.push({tag:el.tagName, type:el.type||'', name:(el.name||'').slice(-16), val:el.value||'', checked:el.checked, lbl, x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2)});
}
return JSON.stringify(out.slice(0,40));

const out=[];
for (const el of document.querySelectorAll('input[type=radio]')) {
  if(!el.checked) continue; const p=el.closest('label')||el.parentElement;
  const r=el.getBoundingClientRect(); if(r.y<700||r.y>1100) continue;
  out.push((p?(p.textContent||'').trim().slice(0,12):'')+ '@'+Math.round(r.y));
}
return JSON.stringify(out);

const t={};
for (const el of document.querySelectorAll('input[type=radio]')) {
  const p=el.closest('label')||el.parentElement; const lbl=p?(p.textContent||'').trim():'';
  if(['Curvy','Pert','Chest'].includes(lbl)){const r=el.getBoundingClientRect(); t[lbl]=Math.round(r.x)+','+Math.round(r.y+r.height/2);}
}
return JSON.stringify(t);

function setRadio(lbl){for(const el of document.querySelectorAll('input[type=radio]')){const p=el.closest('label')||el.parentElement; if(p && (p.textContent||'').trim()===lbl){el.click(); return true;}}return false;}
const r1=setRadio('Curvy'), r2=setRadio('Pert');
// read final checked build in body section
